#!/usr/bin/env python3
"""A4-PR2 rework mutation proofs (items 1-3). Production flips only."""
import os, shutil, subprocess
PL='packages/runtime/src/plugin/permission-plane.ts'; HO='packages/runtime/src/plugin/host.ts'
DO='packages/domain/authority-envelope/src/authority-envelope.ts'; SV='packages/runtime/governance/service.ts'
T='packages/runtime/test/a4p2-dual-envelope-mutation.test.ts'
OUT='dev/agent-workflow/evidence/a4-pr2/mutation-proofs/lane-c-rework-mutation-proofs.txt'
lines=[f"# A4-PR2 rework proofs (items 1-3) - generated by generate-lane-c-rework.py.",
       f"# HEAD {subprocess.run(['git','rev-parse','--short','HEAD'],capture_output=True,text=True).stdout.strip()}.",
       "# Restore is from a saved COPY (never `git checkout --`).",""]
def run(label, path, old, new, expect='RED'):
    src=open(path).read(); bak=path+'.prbak'; shutil.copyfile(path,bak)
    if src.count(old)!=1:
        lines.append(f"## {label}\n- ANCHOR ERROR count={src.count(old)} - not run\n"); os.remove(bak)
    else:
        open(path,'w').write(src.replace(old,new))
        p=subprocess.run(['npx','vitest','run',T],capture_output=True,text=True)
        tail=[l.strip() for l in (p.stdout+p.stderr).split('\n') if l.strip().startswith('Tests ')]
        failed=p.returncode!=0
        lines.append(f"## {label}\n- file: {path}\n- flip: {old.strip()[:90]!r}\n- result: {tail[0] if tail else 'no summary'}\n- verdict: {'RED (noticed)' if failed else 'GREEN (nothing noticed)'}\n- expected: {expect}  - as expected: {failed == (expect=='RED')}\n")
        shutil.move(bak,path)
    open(OUT,'w').write('\n'.join(lines))
r=[]
run('R1 the host stopped injecting the ceiling reader',HO,'permissionAuthorityCeiling: createAuthorityCeilingReader({ facts: permissionFacts }),','// permissionAuthorityCeiling: (not injected)')
run('R2 the lane factory stopped forwarding the reader',PL,'    ...(authorityCeiling === undefined ? {} : { authorityCeiling }),','    // not forwarded')
run('R3 the v3 switch widened to v2 (the existential branch deleted)',PL,'    if (schemaVersion !== 3) return undefined','    if (schemaVersion === 1) return undefined')
run('R4 the v3 switch inferred v1/v2 from an EMPTY hard ceiling (rules.length)',PL,'    if (schemaVersion !== 3) return undefined','    if (schemaVersion !== 3) return undefined\n    {\n      const raw = await deps.facts.teamHardEnvelope(teamSessionId, memberInstanceId) as { rules?: unknown[]; document?: { rules?: unknown[] } }\n      const d = raw.document ?? raw\n      if (Array.isArray(d.rules) && d.rules.length === 0) return undefined\n    }')
run('R5 the trusted operator normalized to human-admin (plan:261)',PL,"actor === 'leader' ? 'leader' : 'human-user'","actor === 'leader' ? 'leader' : 'human-admin'")
run('R6 the approval no-match default became no-authority (planes EQUAL: the property still holds, informational)',DO,
    "    case 'no-match':\n      return CEILING_IDENTITY","    case 'no-match':\n      return CEILING_NO_AUTHORITY", expect='GREEN')
run('R7 the approval lookup forced deny on a MATCH (non-vacuity of the C7 property leg)',DO,
    "      return CEILING_IDENTITY\n    case 'matched':\n      return decided(outcome.effect, outcome.matchedRules)",
    "      return CEILING_IDENTITY\n    case 'matched':\n      return decided('deny', outcome.matchedRules)")
run('R8 the judge dropped the APPROVAL plane from its loop (EXPECTED green: C7 theorem — the row cannot bind while both planes see the same documents+scope; R7 proves the property leg notices if the law itself changes)',SV,
    "            ['approval', approval] as const,","", expect='GREEN')
lines.append(f"\n# Recorded results below; R8 is EXPECTED green and argued in the commit message.\n")
open(OUT,'w').write('\n'.join(lines)); print(open(OUT).read().count('- verdict'), 'proofs; RED:', open(OUT).read().count('verdict: RED'))
